(()=>{'use strict';
const molecules={methane:{c:1,h:4,o:0},methanol:{c:1,h:4,o:1},ethene:{c:2,h:4,o:0},ethane:{c:2,h:6,o:0},ethyne:{c:2,h:2,o:0}};
function formation(s){if(s==='co2')return{carbon:-1,oxygen:-1,co2:1};if(s==='water')return{hydrogen:-1,oxygen:-.5,water:1};const a=molecules[s];const v={carbon:-a.c,hydrogen:-a.h/2,[s]:1};if(a.o)v.oxygen=-a.o/2;return v;}
function combustion(s){if(s==='hydrogen')return{hydrogen:-1,oxygen:-.5,water:1};const a=molecules[s];return{[s]:-1,oxygen:-(a.c+a.h/4-a.o/2),co2:a.c,water:a.h/2};}
function make(mode,index){if(mode==='formation'){const fuel=Object.keys(molecules)[index%5],a=molecules[fuel];return{target:combustion(fuel),reactions:[{v:formation(fuel),symbol:fuel},{v:formation('co2'),symbol:'co2'},{v:formation('water'),symbol:'water'}],solution:[-1,a.c,a.h/2]};}const [start,end,h]=[['ethene','ethane',1],['ethyne','ethane',2],['ethyne','ethene',1]][index%3];return{target:{[start]:-1,hydrogen:-h,[end]:1},reactions:[{v:combustion(start),symbol:start},{v:combustion('hydrogen'),symbol:'hydrogen'},{v:combustion(end),symbol:end}],solution:[1,h,-1]};}
if(typeof module!=='undefined'&&module.exports)module.exports={formation,combustion,make,molecules};if(typeof document==='undefined')return;
const H=window.ChemiHess,$=id=>document.getElementById('hs-'+id);if(!$('game')||!H)return;let mode='formation',index=Math.floor(Math.random()*5),p=make(mode,index),factors=[1,1,1];
const amount=x=>H.amount(Math.abs(x)),scaled=(v,f)=>Object.fromEntries(Object.entries(v).map(([s,n])=>[s,n*f])),data=()=>p.reactions.map(r=>({...r,h:0})),combined=()=>H.combine(data(),factors);
function symbol(s){return 'ΔH°<sub>'+ (mode==='formation'?'f':'c')+'</sub>['+H.species[s]+']';}
function expression(){return p.reactions.map((r,i)=>{const f=factors[i],sign=f<0?'−':i?' + ':'';return sign+(Math.abs(f)===1?'':amount(f)+' ')+symbol(r.symbol);}).join(' ');}
function render(){const net=combined().net;$('target').innerHTML=H.colouredEquation(p.target,p.target,net);$('rows').innerHTML=p.reactions.map((r,i)=>`<div class="hp-row"><header><strong>Reaction ${i+1}</strong><span>Factor ${factors[i]<0?'−':''}${amount(factors[i])}</span></header><p class="hp-original">Given: ${H.colouredEquation(r.v)} · ΔH° = ${symbol(r.symbol)}</p><div class="hp-adjusted"><div class="hp-equation">${H.colouredEquation(scaled(r.v,factors[i]),p.target,net)}</div><strong class="hp-enthalpy">ΔH° = ${factors[i]<0?'−':''}${Math.abs(factors[i])===1?'':amount(factors[i])+' '}${symbol(r.symbol)}</strong></div><div class="hp-tools"><button type="button" data-op="flip" data-row="${i}">Flip ⇄</button><label>Factor<input data-operand="${i}" type="number" min="0.125" max="8" step="any" value="2" aria-label="Multiplier or divisor for reaction ${i+1}"></label><button type="button" data-op="multiply" data-row="${i}">Multiply ×</button><button type="button" data-op="divide" data-row="${i}">Divide ÷</button><button type="button" data-op="reset" data-row="${i}">Reset</button></div></div>`).join('');$('live-expression').innerHTML='ΔH° = '+expression();$('result').hidden=true;$('feedback').textContent='';}
$('rows').addEventListener('click',e=>{const b=e.target.closest('[data-op]');if(!b)return;const i=+b.dataset.row,op=b.dataset.op,input=$('rows').querySelector(`[data-operand="${i}"]`),value=+input.value;if(['multiply','divide'].includes(op)&&(!Number.isFinite(value)||value<=0||value>8)){$('feedback').textContent='Use a positive factor no greater than 8.';return;}const next=op==='flip'?-factors[i]:op==='reset'?1:factors[i]*(op==='multiply'?value:1/value);if(Math.abs(next)<1/64||Math.abs(next)>64){$('feedback').textContent='Keep the overall factor between 1/64 and 64.';return;}factors[i]=next;render();});
$('combine').addEventListener('click',()=>{const c=combined(),match=H.matches(c.net,p.target);$('result').hidden=false;$('net').innerHTML=H.colouredEquation(c.net,p.target,c.net);const cancelled=Object.entries(c.cancelled).filter(([,n])=>n>1e-8);$('cancelled').innerHTML=cancelled.length?'Cancelled from each side: '+cancelled.map(([s,n])=>`<span class="hp-cancel">${n===1?'':H.amount(n)+' '}${H.species[s]}</span>`).join(' + '):'No substances cancel.';$('feedback').textContent=match?'The combined reaction matches the target.':'Adjust the equations until the combined reaction matches the target.';$('rule').hidden=!match;$('rule').innerHTML=mode==='formation'?'ΔH°<sub>reaction</sub> = ΣνΔH°<sub>f</sub>(products) − ΣνΔH°<sub>f</sub>(reactants)':'ΔH°<sub>reaction</sub> = ΣνΔH°<sub>c</sub>(reactants) − ΣνΔH°<sub>c</sub>(products)';$('rule-note').hidden=!match;$('rule-note').textContent=mode==='formation'?'ν is the coefficient in the target reaction. Elements in their standard states have ΔH°f = 0; the O₂ term is therefore zero.':'ν is the coefficient in the target reaction. Both routes must end at the same combustion products in the same physical states.';});
function restart(){factors=[1,1,1];render();}
$('reset').addEventListener('click',restart);$('next').addEventListener('click',()=>{const count=mode==='formation'?5:3;index=(index+1+Math.floor(Math.random()*(count-1)))%count;p=make(mode,index);restart()});
for(const value of ['numerical','formation','combustion'])document.getElementById('hess-mode-'+value).addEventListener('click',()=>{for(const v of ['numerical','formation','combustion'])document.getElementById('hess-mode-'+v).setAttribute('aria-pressed',String(v===value));document.getElementById('hess-numerical').hidden=value!=='numerical';$('game').hidden=value==='numerical';if(value!=='numerical'){mode=value;index=Math.floor(Math.random()*(mode==='formation'?5:3));p=make(mode,index);$('mode-name').textContent=mode==='formation'?'Formation enthalpies · ΔH°f':'Combustion enthalpies · ΔH°c';restart();}});render();
})();
